package identity

import (
	"encoding/json"
	"os"
	"testing"
)

// testdata/user-tokens.json is generated by the TypeScript signer and
// verified there too. A case one language accepts and the other refuses is a
// token that works on some services and not others.
type fixture struct {
	PublicKeys   string `json:"publicKeys"`
	LegacySecret string `json:"legacySecret"`
	Cases        []struct {
		Name   string `json:"name"`
		Token  string `json:"token"`
		Legacy bool   `json:"legacy"`
		Expect *struct {
			Sub      string `json:"sub"`
			Email    string `json:"email"`
			Role     string `json:"role"`
			TenantID string `json:"tenantId"`
			Portal   Portal `json:"portal"`
			Legacy   bool   `json:"legacy"`
		} `json:"expect"`
	} `json:"cases"`
}

func loadFixture(t *testing.T) fixture {
	t.Helper()
	raw, err := os.ReadFile("testdata/user-tokens.json")
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var f fixture
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	return f
}

func TestUserTokensMatchTheSharedFixtures(t *testing.T) {
	f := loadFixture(t)
	verifier, err := NewUserTokenVerifier(f.PublicKeys, f.LegacySecret)
	if err != nil {
		t.Fatalf("verifier: %v", err)
	}
	for _, c := range f.Cases {
		t.Run(c.Name, func(t *testing.T) {
			claims, err := verifier.Verify(c.Token)
			if c.Expect == nil {
				if err == nil {
					t.Fatalf("expected refusal, got %+v", claims)
				}
				return
			}
			if err != nil {
				t.Fatalf("expected acceptance, got %v", err)
			}
			got := [6]any{claims.Subject, claims.Email, claims.Role, claims.TenantID, claims.Portal, claims.Legacy}
			want := [6]any{c.Expect.Sub, c.Expect.Email, c.Expect.Role, c.Expect.TenantID, c.Expect.Portal, c.Expect.Legacy}
			if got != want {
				t.Fatalf("claims %v, want %v", got, want)
			}
		})
	}
}

func TestOlderTokensAreRefusedOnceTheWindowCloses(t *testing.T) {
	f := loadFixture(t)
	strict, err := NewUserTokenVerifier(f.PublicKeys, "")
	if err != nil {
		t.Fatalf("verifier: %v", err)
	}
	for _, c := range f.Cases {
		if !c.Legacy {
			continue
		}
		if _, err := strict.Verify(c.Token); err == nil {
			t.Fatalf("%s: accepted without the legacy secret", c.Name)
		}
	}
}

func TestMalformedPublicKeysAreRejected(t *testing.T) {
	if _, err := NewUserTokenVerifier("k1:not-a-key", ""); err == nil {
		t.Fatal("expected a malformed key to be rejected")
	}
}
